def coindSubtypeEquivPi (A : Rep.{max u v w} k S) :
    Rep.coind S.subtype A ≃ₗ[k]
      (Quotient (QuotientGroup.rightRel S) → A)

def indSubtypeEquivPi [S.FiniteIndex] (A : Rep.{max u v w} k S) :
