theorem indFDRepMap_comp {k G : Type u} [Field k] [Group G] {S : Subgroup G}
    [S.FiniteIndex] {A B C : FDRep k S} (f : A ⟶ B) (g : B ⟶ C) :
    indFDRepMap (f ≫ g) = indFDRepMap f ≫ indFDRepMap g

theorem finrank_indFDRep {k G : Type u} [Field k] [Group G] {S : Subgroup G}
    [S.FiniteIndex] (A : FDRep k S) :
    Module.finrank k (indFDRep A) = S.index * Module.finrank k A

def indTrivialEquiv :
    ((Representation.trivial k H k).ind H.subtype).Equiv
      (Representation.ofMulAction k G (G ⧸ H))

theorem char_ind_trivial [Finite (G ⧸ H)] (g : G) :
    ((Representation.trivial k H k).ind H.subtype).character g =
      Nat.card {q : G ⧸ H // g • q = q}

theorem comp_eq_nil (h : Quiver.IsAcyclic V) {a b : V}
    (p : Path a b) (q : Path b a) :
    p.comp q = Path.nil

theorem length_eq_zero_of_paths_left (h : Quiver.IsAcyclic V) {a b : V}
    (p : Path a b) (q : Path b a) :
    p.length = 0

theorem length_eq_zero_of_paths_right (h : Quiver.IsAcyclic V) {a b : V}
    (p : Path a b) (q : Path b a) :
    q.length = 0

theorem eq_of_paths (h : Quiver.IsAcyclic V) {a b : V}
    (p : Path a b) (q : Path b a) :
    a = b

theorem not_nonempty_path_and_nonempty_path (h : Quiver.IsAcyclic V) {a b : V}
    (hab : a ≠ b) :
    ¬(Nonempty (Path a b) ∧ Nonempty (Path b a))

theorem isEmpty_path_of_path (h : Quiver.IsAcyclic V) {a b : V}
    (hab : a ≠ b) (p : Path a b) :
    IsEmpty (Path b a)

theorem length_lt_card (h : Quiver.IsAcyclic V) [Fintype V] {a b : V}
    (p : _root_.Quiver.Path a b) :
    p.length < Fintype.card V

theorem hom_reflect_reflect (i a b : V) :
    @_root_.Quiver.Hom (Reflect (Reflect V i) i) (reflectQuiver (V := Reflect V i) i) a b =
      (a ⟶ b)

theorem vertexPreReflection_apply_of_titsPolarForm_eq_zero (i : Q) {d : Q → ℤ}
    (hd : titsPolarForm Q (Pi.single i 1) d = 0) :
    vertexPreReflection Q i d = d

theorem bijOn_vertexPreReflection {i : Q} (h : IsEmpty (i ⟶ i)) (n : ℤ) :
    Set.BijOn (vertexPreReflection Q i) {d : Q → ℤ | titsForm Q d = n}
      {d : Q → ℤ | titsForm Q d = n}

theorem sum_sum_eq_of_add_swap_eq {W : Type*} [Fintype W] {F G : W → W → ℤ}
    (h : ∀ a b : W, F a b + F b a = G a b + G b a) :
    ∑ a : W, ∑ b : W, F a b = ∑ a : W, ∑ b : W, G a b

